import random

def calculate_sum(adj):
    n = len(adj)
    degrees = [sum(row) for row in adj]
    s = 0
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i][j]:
                s += abs(degrees[i] - degrees[j])
    return s

def get_random_graph(n):
    adj = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < 0.5:
                adj[i][j] = adj[j][i] = 1
    return adj

def hill_climb(n, iterations=1000):
    adj = get_random_graph(n)
    current_s = calculate_sum(adj)

    for _ in range(iterations):
        # Try adding, removing, or flipping an edge
        i = random.randint(0, n - 1)
        j = random.randint(0, n - 1)
        if i == j: continue
        if i > j: i, j = j, i

        # Flip edge
        adj[i][j] = adj[j][i] = 1 - adj[i][j]
        new_s = calculate_sum(adj)

        if new_s >= current_s:
            current_s = new_s
        else:
            # backtrack
            adj[i][j] = adj[j][i] = 1 - adj[i][j]

    return current_s

