def generate_degree_sequences(n):
    # Generate all non-increasing sequences d_1 >= d_2 >= ... >= d_n
    # such that 0 <= d_i <= n-1 and sum(d_i) is even.
    def backtrack(idx, last_val, current_sum):
        if idx == n:
            if current_sum % 2 == 0:
                yield []
            return

        for val in range(min(last_val, n - 1), -1, -1):
            for rest in backtrack(idx + 1, val, current_sum + val):
                yield [val] + rest

    return backtrack(0, n - 1, 0)

