import random

def calculate_sum(adj, degrees):
    n = len(adj)
    s = 0
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i][j]:
                s += abs(degrees[i] - degrees[j])
    return s

def get_random_graph(n):
    adj = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if random.random() < 0.5:
                adj[i][j] = adj[j][i] = 1
    return adj

def hill_climb(n, iterations=10000):
    adj = get_random_graph(n)
    degrees = [sum(row) for row in adj]
    current_s = calculate_sum(adj, degrees)

    for _ in range(iterations):
        u = random.randint(0, n - 1)
        v = random.randint(0, n - 1)
        if u == v: continue
        if u > v: u, v = v, u

        # Flip edge (u, v)
        if adj[u][v] == 0:
            adj[u][v] = adj[v][u] = 1
            degrees[u] += 1
            degrees[v] += 1
        else:
            adj[u][v] = adj[v][u] = 0
            degrees[u] -= 1
            degrees[v] -= 1

        new_s = calculate_sum(adj, degrees)
        if new_s >= current_s:
            current_s = new_s
        else:
            if adj[u][v] == 1:
                adj[u][v] = adj[v][u] = 0
                degrees[u] -= 1
                degrees[v] -= 1
            else:
                adj[u][v] = adj[v][u] = 1
                degrees[u] += 1
                degrees[v] += 1
    return current_s

