def solve_brute_force(n):
    max_s = 0
    edges = list(itertools.combinations(range(n), 2))
    num_edges = len(edges)
    for i in range(1 << num_edges):
        adj = [[0]*n for _ in range(n)]
        for j in range(num_edges):
            if (i >> j) & 1:
                u, v = edges[j]
                adj[u][v] = adj[v][u] = 1

        degrees = [sum(row) for row in adj]
        s = calculate_sum(adj, degrees)
        if s > max_s:
            max_s = s
    return max_s

for n in range(1, 8):
    print(f"n={n}, max_s={solve_brute_force(n)}")
